/* the change in format when this extended role selection was converted from
   tty-only to tty+curses+? made the role selection menu require two pages
   on a traditional 24-line tty; that wasn't fair to tty, so squeeze out
   some blank separator lines from the menu if that will make it fit on one */
/**
 * @param {number} rows int
 * @param {number} aspect int
 * @returns {number} int
 */
function maybe_skip_seps(rows, aspect) {   // role.c:2777
    let i = 0;
    let n = 0;
    /* not much point to generalizing this to other aspects */
    if (aspect !== RS.ROLE) {
        return 0;
    }
    /*
     * If there are one or two excess lines, setup_rolemenu() will omit
     * the separator between 'random' and 'pick race first'.  If there are
     * two, plsel_startmenu() will omit the one between role info so far
     * ("<role> <race> ...") and the set of role entries.
     */
    n = n + 4 | 0;   /* title and ensuing separator, role info so far and separator */
    for (i = 0; roles[i].name.m; i = i + 1 | 0) {
        if (ok_role(i, flags.initrace, flags.initgend, flags.initalign) && ok_race(i, flags.initrace, flags.initgend, flags.initalign)
            && ok_gend(i, flags.initrace, flags.initgend, flags.initalign) && ok_align(i, flags.initrace, flags.initgend, flags.initalign)) {
            n = n + 1 | 0;
        }
    }
    n = n + 2 | 0;   /* 'random' and separator */
    n = n + 5 | 0;   /* race 1st, gender 1st, alignment 1st, reset filter, quit */
    n = n + 1 | 0;   /* footer/prompt */
    if (rows > 0 && n > rows) {
        return n - rows | 0;
    }
    return 0;
}
/* start a menu; show role aspects specified so far as a header line */
/**
 * @param {number} ttyrows int
 * @param {number} aspect int
 * @returns {Promise<number>} winid
 */
async function plsel_startmenu(ttyrows, aspect) {   // role.c:2806
    let qbuf = new Int8Array(128);
    /* whatever aspect was just chosen might force others (Orc => chaotic,
       Samurai => Human+lawful, Valkyrie => female) */
    rigid_role_checks();
    const rolename = flags.initrole < 0 ? $C`<role>`
        : flags.initgend === 1 && roles[flags.initrole].name.f ? roles[flags.initrole].name.f
        : roles[flags.initrole].name.m;
    if (!svp.plname[0] || flags.initrole < 0 || flags.initrace < 0 || flags.initgend < 0 || flags.initalign < 0) {
        /* "<role> <race.noun> <gender> <alignment>" */
        $c.sprintf(new $c.Ptr(qbuf, 0), $C`%.20s %.20s %.20s %.20s`, rolename, flags.initrace < 0 ? $C`<race>` : races[flags.initrace].noun, flags.initgend < 0 ? $C`<gender>` : genders[flags.initgend].adj, flags.initalign < 0 ? $C`<alignment>` : aligns[flags.initalign].adj);
    } else {
        /* "<name> the <alignment> <gender> <race.adjective> <role>" */
        $c.sprintf(new $c.Ptr(qbuf, 0), $C`%.20s the %.20s %.20s %.20s %.20s`, new $c.Ptr(svp.plname, 0), aligns[flags.initalign].adj, genders[flags.initgend].adj, races[flags.initrace].adj, rolename);
    }
    const win = await create_nhwindow()(NHW.MENU);
    if (win === WIN_ERR) {
        await panic($C`could not create role selection window`);
    }
    await start_menu()(win, MENU.BEHAVE_STANDARD);
    await add_menu_str(win, new $c.Ptr(qbuf, 0));
    if (maybe_skip_seps(ttyrows, aspect) !== 2) {
        await add_menu_str(win, $C``);
    }
    return win;
}
/* add entries a-Archeologist, b-Barbarian, &c to menu being built in 'win' */
/**
 * @param {number} win winid
 * @param {number} filtering boolean
 * @param {number} race int
 * @param {number} gend int
 * @param {number} algn int
 * @returns {Promise<void>}
 */
async function setup_rolemenu(win, filtering, race, gend, algn) {   // role.c:2854
    let any = new $T.any(), i = 0, rolenamebuf = new Int8Array(50);
    /* True => exclude filtered roles;
     * False => filter reset */
    /* all ROLE_NONE for !filtering case */
    let lastch = 0;
    const clr = NO_COLOR;
    any.$copyFrom(cg.zeroany);   /* zero out all bits */
    for (i = 0; roles[i].name.m; i = i + 1 | 0) {
        /* role can be constrained by any of race, gender, or alignment */
        const role_ok = ok_role(i, race, gend, algn)
            && ok_race(i, race, gend, algn)
            && ok_gend(i, race, gend, algn)
            && ok_align(i, race, gend, algn) ? 1 : 0;
        if (filtering && !role_ok) {
            continue;
        }
        if (filtering) {
            any.a_int = i + 1 | 0;
        } else {
            any.a_string = roles[i].name.m;
        }
        let thisch = lowc(roles[i].name.m.get(0));
        if (thisch === lastch) {
            thisch = highc(thisch);
        }
        $c.strcpy(new $c.Ptr(rolenamebuf, 0), roles[i].name.m);
        if (roles[i].name.f) {
            /* role has distinct name for female (C,P) */
            if (gend === 1) {
                /* female already chosen; replace male name */
                $c.strcpy(new $c.Ptr(rolenamebuf, 0), roles[i].name.f);
            } else if (gend < 0) {
                /* not chosen yet; append slash+female name */
                $c.strcat(new $c.Ptr(rolenamebuf, 0), $C`/`);
                $c.strcat(new $c.Ptr(rolenamebuf, 0), roles[i].name.f);
            }
        }
        /* !filtering implies reset_role_filtering() where we want to
           mark this role as preselected if current filter excludes it */
        await add_menu(win, nul_glyphinfo, any, thisch, 0,
            ATR.NONE, clr, await an(new $c.Ptr(rolenamebuf, 0)),
            !filtering && !role_ok
            ? MENU.ITEMFLAGS_SELECTED : MENU.ITEMFLAGS_NONE);
        lastch = thisch;
    }
}
/**
 * @param {number} win winid
 * @param {number} filtering boolean
 * @param {number} role int
 * @param {number} gend int
 * @param {number} algn int
 * @returns {Promise<void>}
 */
async function setup_racemenu(win, filtering, role, gend, algn) {   // role.c:2905
    let any = new $T.any(), i = 0;
    const clr = NO_COLOR;
    any.$copyFrom(cg.zeroany);
    for (i = 0; races[i].noun; i = i + 1 | 0) {
        /* no ok_gend(); race isn't constrained by gender */
        const race_ok = ok_race(role, i, gend, algn)
            && ok_role(role, i, gend, algn)
            && ok_align(role, i, gend, algn) ? 1 : 0;
        if (filtering && !race_ok) {
            continue;
        }
        if (filtering) {
            any.a_int = i + 1 | 0;
        } else {
            any.a_string = races[i].noun;
        }
        const this_ch = races[i].noun.get(0);
        /* filtering: picking race, so choose by first letter, with
           capital letter as unseen accelerator;
           !filtering: resetting filter rather than picking, choose by
           capital letter since lowercase role letters will be present */
        await add_menu(win, nul_glyphinfo, any,
            filtering ? this_ch : highc(this_ch),
            filtering ? highc(this_ch) : 0,
            ATR.NONE, clr, races[i].noun,
            !filtering && !race_ok
            ? MENU.ITEMFLAGS_SELECTED : MENU.ITEMFLAGS_NONE);
    }
}
